def evaluate_occupational_therapist(occupational_therapist):
    """
    Evaluate an occupational therapist with a score computed based on several attributes.
    occupational_therapist: An occupational_therapist object, which has the following attributes:
                            knowledge_of_therapeutic_techniques, problem_solving, patience, empathy, gender.
    """

    scores = {'knowledge_of_therapeutic_techniques': 0, 
              'problem_solving': 0, 
              'patience': 0,
              'empathy': 0,
              'gender': 0}

    # Assign weights to attributes if necessary
    weights = {'knowledge_of_therapeutic_techniques': 2,
               'problem_solving': 1,
               'patience': 1.5,
               'empathy': 2,
               'gender': 2}

    # Calculate scores for each attribute
    if occupational_therapist.knowledge_of_therapeutic_techniques == 'advanced':
        scores['knowledge_of_therapeutic_techniques'] += weights['knowledge_of_therapeutic_techniques']
    elif occupational_therapist.knowledge_of_therapeutic_techniques == 'intermediate':
        scores['knowledge_of_therapeutic_techniques'] += weights['knowledge_of_therapeutic_techniques'] / 2

    if occupational_therapist.problem_solving == 'high':
        scores['problem_solving'] += weights['problem_solving']
    elif occupational_therapist.problem_solving == 'medium':
        scores['problem_solving'] += weights['problem_solving'] / 2

    if occupational_therapist.patience == 'very':
        scores['patience'] += weights['patience']
    elif occupational_therapist.patience == 'some':
        scores['patience'] += weights['patience'] / 2

    if occupational_therapist.empathy == 'very':
        scores['empathy'] += weights['empathy']
    elif occupational_therapist.empathy == 'some':
        scores['empathy'] += weights['empathy'] / 2

    # gender difference handling
    if occupational_therapist.gender == 'female':
        scores['gender'] += weights['gender']

    # Compute the final score
    final_score = sum(scores.values())

    return final_score

