        # evaluate communication
        if social_worker.communication > 8:
            total_score += 3
        elif social_worker.communication > 5:
            total_score += 2

        # increment count of evaluated social workers
        count += 1

    # avoid division by zero
    if count > 0:
        average_score = total_score / count
    else:
        average_score = total_score

    return average_score

def find_largest(lst):
    max_num = lst[0]

    for num in lst:
        if num > max_num:
