        'empathy': 0,
        'problem_solving': 0,
        'communication': 0,
        'gender_count': 0
    }

    for therapist in therapists_all:
        try:
            scores['patience'] += therapist.patience
            scores['empathy'] += therapist.empathy
            scores['problem_solving'] += therapist.problem_solving
